import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api/user';

function App() {
  // ===== CORE STATE =====
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(new Set());
  const [formData, setFormData] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [responseMessage, setResponseMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [errorDetails, setErrorDetails] = useState('');
  const [smsConversation, setSmsConversation] = useState([]);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [phoneNumber, setPhoneNumber] = useState('');
  const [serverStatus, setServerStatus] = useState('checking');
  const [activationDone, setActivationDone] = useState(false);
  const [showRegistrationComplete, setShowRegistrationComplete] = useState(false);
  const [myPhone, setMyPhone] = useState('0712345678');

  // ===== DASHBOARD STATE =====
  const [allMatches, setAllMatches] = useState([]);
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [myMatches, setMyMatches] = useState([]);
  const [chatMessages, setChatMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [activeChatUser, setActiveChatUser] = useState(null);
  const [activeTab, setActiveTab] = useState('discover');
  const [showProfile, setShowProfile] = useState(false);
  const [showMatchDetails, setShowMatchDetails] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState(null);
  const [requestStatus, setRequestStatus] = useState(null);
  const [myInterests, setMyInterests] = useState([]);

  // ============================================
  // API 1: Service Activation
  // API 2: Service Registration
  // API 3: Complete Profile
  // API 5: Self-Description
  // API 6: Matching Request (SMS)
  // API 7: Search Matches (GET)
  // API 8: Next Matches (GET)
  // API 9: Send Profile SMS
  // API 10: Notify Interest
  // API 11: Get Self-Description
  // API 12: Incoming SMS
  // API 13: Get User Profile
  // API 14: Get Profile Details
  // API 15: Consent Confirmation
  // API 16: Accept Request
  // API 17: Reject Request
  // API 18: View Request Status
  // API 19: View My Interests
  // API 20: Express Interest
  // ============================================

  // ============================================
  // API CALL FUNCTIONS
  // ============================================

  // API 1: Service Activation
  const callActivation = async () => {
    try {
      const response = await fetch(`${API_BASE}/activate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ penzi: 'penzi' })
      });
      return await response.json();
    } catch (error) {
      console.error('Activation API error:', error);
      return null;
    }
  };

  // API 2: Service Registration
  const callRegistration = async (data) => {
    try {
      const response = await fetch(`${API_BASE}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          phone_number: data.phone_number,
          name: data.name,
          age: data.age,
          gender: data.gender,
          county: data.county,
          town: data.town
        })
      });
      return await response.json();
    } catch (error) {
      console.error('Registration API error:', error);
      return null;
    }
  };

  // API 3: Complete Profile
  const callCompleteProfile = async (phone, data) => {
    try {
      const response = await fetch(`${API_BASE}/${phone}/complete-profile`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          education_level: data.education_level,
          profession: data.profession,
          marital_status: data.marital_status,
          religion: data.religion,
          ethnicity: data.ethnicity
        })
      });
      return await response.json();
    } catch (error) {
      console.error('Complete Profile API error:', error);
      return null;
    }
  };

  // API 5: Self-Description
  const callSelfDescription = async (phone, description) => {
    try {
      const response = await fetch(`${API_BASE}/${phone}/self-description`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ description: description })
      });
      return await response.json();
    } catch (error) {
      console.error('Self-Description API error:', error);
      return null;
    }
  };

  // API 6: Matching Request (SMS)
  const callMatchingRequest = async (phone, message) => {
    try {
      const response = await fetch(`${API_BASE}/sms`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          phone_number: phone,
          message: message
        })
      });
      return await response.json();
